"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["59734"],{53404(e){e.exports=JSON.parse('{"id":"FIN-820","slug":"student-loan","term":"Student Loan","also_known_as":[],"difficulty":"Beginner","definition":"A student loan is money borrowed to pay for education costs, such as tuition fees, books and living expenses, usually repaid after the student finishes or leaves their studies.","explanation":["Student loans are offered by governments, private lenders or both, depending on the country. Government loans often have special features designed to make them more affordable, such as lower interest rates, no credit checks and repayments linked to income.","In some countries, such as the United Kingdom and Australia, government student loan repayments depend on income. Graduates repay a percentage of their earnings above a set threshold, and any remaining balance may be written off after a certain number of years. In the United States, federal student loans offer several repayment plans, including income-driven options, while private student loans usually work more like ordinary loans with fixed monthly payments.","For example, under an income-contingent system, a graduate earning just above the repayment threshold might repay only a small amount each month, while one earning well above it would repay more.","Student loans can make education accessible to people who could not otherwise afford it. However, large balances can take many years to repay, and borrowers should understand the interest rate, repayment terms and any options for deferment or forgiveness."],"note":"","total":1500,"prev":{"slug":"stub-period","term":"Stub Period"},"next":{"slug":"subordinated-debt","term":"Subordinated Debt"}}')}}]);